/* 양도 게시글 수정 */ UPDATE transfer_board
individual_grants = #{individualGrants} ,
transfer_title = #{transferTitle},
transfer_content = #{transferContent},
revision_date = NOW()
WHERE transfer_board_no = #{transferBoardNum};

mapper.insert:
  		/* 등록 */
  		INSERT INTO transfer_board
		(transfer_board_no, cust_id, rental_contract_no, sell_products_no, model_no, item_no, product_category_no, del_info_no, transfer_title, transfer_content, rental_fee, remaining_months, contract_end_date, individual_grants, board_valid_date, transfer_rental_processing_status, register_date, revision_date)
